<section class="page-heading"><div><p class="eyebrow">PERSONNALISEZ VOTRE CLASSIFICATION</p><h1>Paramètres</h1><p class="subheading">Gérez les libellés partagés, puis vos catégories et sous-catégories. Les modifications des éléments de base sont visibles par tous les comptes.</p></div><a class="button secondary" href="<?= e(url('profile')) ?>">Profil et thème</a></section>

<section class="taxonomy-panel form-panel"><div class="panel-heading"><span class="panel-index">01</span><div><h2>Libellés principaux</h2><p>Les libellés organisent les grandes familles de pièces et sont communs à l’application.</p></div></div>
<form class="taxonomy-create" method="post" action="<?= e(url('label-save')) ?>"><?= csrf_field() ?><label>Nouveau libellé<input name="name" maxlength="40" required placeholder="Ex. Tenues de sport"></label><button class="button primary">Ajouter le libellé</button></form>
<div class="taxonomy-list"><?php foreach($labels as $label): ?><div class="taxonomy-row"><form method="post" action="<?= e(url('label-save')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($label['id']) ?>"><label class="sr-only" for="label-<?= e($label['id']) ?>">Nom du libellé</label><input id="label-<?= e($label['id']) ?>" name="name" maxlength="40" required value="<?= e($label['name']) ?>"><button class="button secondary">Enregistrer</button></form><form method="post" action="<?= e(url('label-delete')) ?>" data-confirm="Supprimer ce libellé partagé ? Il doit d’abord être retiré des pièces, envies et catégories."><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($label['id']) ?>"><button class="button danger">Supprimer</button></form></div><?php endforeach; ?></div></section>

<div class="settings-columns taxonomy-columns"><section class="form-panel"><div class="panel-heading"><span class="panel-index">02</span><div><h2>Catégories</h2><p>Modifiez les catégories de base ou ajoutez-en une privée à votre compte.</p></div></div>
<form class="taxonomy-create" method="post" action="<?= e(url('category-save')) ?>"><?= csrf_field() ?><label>Libellé principal<select name="label_id" required><?php foreach($activeLabels as $label): ?><option value="<?= e($label['id']) ?>"><?= e($label['name']) ?></option><?php endforeach; ?></select></label><label>Nom<input name="name" required maxlength="80"></label><button class="button primary">Ajouter</button></form>
<div class="taxonomy-list"><?php foreach($categories as $category): ?><article class="taxonomy-item"><form class="taxonomy-edit" method="post" action="<?= e(url('category-edit')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($category['id']) ?>"><label>Libellé<select name="label_id" required><?php foreach($labels as $label): ?><option value="<?= e($label['id']) ?>" <?= (int)$label['id']===(int)$category['label_id']?'selected':'' ?> <?= !(int)$label['is_active']?'disabled':'' ?>><?= e($label['name']) ?></option><?php endforeach; ?></select></label><label>Catégorie<input name="name" maxlength="80" required value="<?= e($category['name']) ?>"></label><span class="taxonomy-scope"><?= $category['is_default']?'Base partagée':'Privée' ?><?= !(int)$category['is_active']?' · inactive':'' ?></span><button class="button secondary">Enregistrer</button></form>
<div class="taxonomy-actions"><form method="post" action="<?= e(url('category-status')) ?>" data-confirm="<?= $category['is_default']?'Ce changement affectera les catégories de base de tous les comptes.':'Changer la disponibilité de cette catégorie ?' ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($category['id']) ?>"><input type="hidden" name="is_active" value="<?= (int)$category['is_active']?0:1 ?>"><button class="button secondary"><?= (int)$category['is_active']?'Désactiver':'Réactiver' ?></button></form><form method="post" action="<?= e(url('category-delete')) ?>" data-confirm="Supprimer cette catégorie<?= $category['is_default']?' partagée':'' ?> ? Elle doit être vide."><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($category['id']) ?>"><button class="button danger">Supprimer</button></form></div></article><?php endforeach; ?></div></section>

<section class="form-panel"><div class="panel-heading"><span class="panel-index">03</span><div><h2>Sous-catégories</h2><p>Renommez, déplacez ou supprimez les sous-catégories.</p></div></div>
<form class="taxonomy-create" method="post" action="<?= e(url('subcategory-save')) ?>"><?= csrf_field() ?><label>Catégorie<select name="category_id" required><?php foreach($categories as $category): if((int)$category['is_active']===1): ?><option value="<?= e($category['id']) ?>"><?= e($category['label_name'].' · '.$category['name']) ?></option><?php endif; endforeach; ?></select></label><label>Nom<input name="name" required maxlength="80"></label><button class="button primary">Ajouter</button></form>
<div class="taxonomy-list"><?php foreach($subcategories as $subcategory): ?><article class="taxonomy-item"><form class="taxonomy-edit" method="post" action="<?= e(url('subcategory-edit')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($subcategory['id']) ?>"><label>Catégorie<select name="category_id" required><?php foreach($categories as $category): if((int)$category['is_active']===1): ?><option value="<?= e($category['id']) ?>" <?= (int)$category['id']===(int)$subcategory['category_id']?'selected':'' ?>><?= e($category['label_name'].' · '.$category['name']) ?></option><?php endif; endforeach; ?></select></label><label>Sous-catégorie<input name="name" maxlength="80" required value="<?= e($subcategory['name']) ?>"></label><span class="taxonomy-scope"><?= $subcategory['user_id']===null?'Base partagée':'Privée' ?></span><button class="button secondary">Enregistrer</button></form><form method="post" action="<?= e(url('subcategory-delete')) ?>" data-confirm="Supprimer cette sous-catégorie ? Les vêtements liés resteront dans leur catégorie."><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($subcategory['id']) ?>"><button class="button danger">Supprimer</button></form></article><?php endforeach; ?></div></section></div>
